namespace MabiCommerceNewLife;

public enum GuideSurface { Main, Inventory, Materials, Settings, RouteMap }

public sealed record GuideTopic(string Title, string Instructions, string TourText,
    GuideSurface Surface, string[] Targets, int Tab = 0)
{
    public string ScreenshotFileName => $"{Surface}-{Targets[0]}.png";
}

public static class UserGuide
{
    public static IReadOnlyList<GuideTopic> Topics { get; } =
    [
        new("1. Your commerce workspace",
            "Use TRADE for standard goods, GROUP for group-commerce goods, and BARTER for material exchanges. Each page keeps separate planner cargo and stock.\n\nThis is a local planner, not an in-game controller. Prices are entered or scanned by you. Route times and unentered prices are estimates, not live readings.",
            "Choose TRADE, GROUP, or BARTER. Each has its own goods and cargo. Use Next/Back to move through the tour; X or Escape exits.",
            GuideSurface.Main, ["TradePageTab", "GroupPageTab", "BarterPageTab"]),
        new("2. Starting post and merchant rating",
            "Choose your starting post from the town dropdown. Enter your Merchant Rating Level for that post to unlock its eligible goods. Ratings are saved per post and can also be edited in Inventory.\n\nBarter has outposts instead of standard buying posts and does not use this rating input.",
            "Choose a starting town or outpost here. Trade/Group goods unlock using your entered Merchant Rating Level; Barter has no rating field.",
            GuideSurface.Main, ["PostPicker"]),
        new("3. Goods",
            "Select a good on the left to edit its prices and stock. Dimmed goods need a higher merchant rating. Scroll for additional goods.\n\nThe small reset-style refresh icon in the paper's upper-left corner receives and applies shared scanned prices when Screen reader mode and Scanned price sharing are enabled in Settings > Calculator Behavior. It stays visible while sharing is off; its info bubble explains how to enable it and shows cooldown seconds. Refresh is limited to once per 60 seconds across all goods/tabs, including failures. Uploads do not trigger downloads; there is no background polling.\n\nGroup/Barter offers have weekly exchange limits. Set a rotating barter offer with its name dropdown when alternatives are available. The app cannot know the current rotation without your selection or scan.",
            "Select a good to view its details and prices. Scroll for more goods. Dimmed goods need a higher merchant rating.",
            GuideSurface.Main, ["ProductList"]),
        new("4. Transport and ownership",
            "Open the transport dropdown and tick the transports you own, then select one. Only owned, mode-eligible transports are available to Auto. Partner/Alpaca variants are optional; flight transports are Group-only.\n\nThe cargo pane shows used slots and weight. Inventory capacity bonuses are included.",
            "Open the dropdown, tick the transports you own, and choose one. Slots and weight limit your load.",
            GuideSurface.Main, ["TransportPicker"]),
        new("5. Your Ducat balance",
            "Enter your available balance in Current Ducats before planning. Trade/Group purchases reduce this planner balance. CLEAR LOAD or removing cargo refunds its purchase cost; Sell does not refund it.\n\nBarter exchanges use materials rather than a Ducat purchase budget. The app never changes your in-game balance.",
            "Enter your available Ducats. Loading uses this budget; clearing refunds the purchase cost. Barter uses materials instead.",
            GuideSurface.Main, ["DucatsInput"]),
        new("6. Manual prices and scanning",
            "On MANUAL, select a good and enter the sale price for each destination. Trade/Group buy prices start as reference estimates until entered or scanned. Group sale calculations apply the destination bonus.\n\nEnable Screen reader mode in Settings to show SCAN. Select the name, Inventory count, and full price list with a small margin around both brackets. SCAN reads prices and Inventory stock, not the quantity slider. Missing entries trigger up to five retries, one capture per second in that same rectangle. Move the mouse/popups clear; if entries stay missing, an error sound and obstruction alert appear with nothing applied.\n\nComplete prices must pass their cross-checks and stock reads must agree to apply automatically; otherwise review them. Missing or uncertain stock stays unchecked; select APPLY STOCK to confirm or correct it, including 0. Saving the last successful region is separately opt-in.\n\nAn accepted scan without Smuggler clears its old quote to 0 and shows Inactive; complete shared observations do the same. Newer local edits still win. A later positive scanned/shared/manual quote reactivates it. A detected but unreadable Smuggler entry still triggers obstruction recovery. Inactive quotes persist and cannot supply Auto/Load Profit/Sell prices.\n\nHover calculation results for the breakdown. -- means the price/time cannot be calculated; Smuggler has no automatic route time.",
            "Enable Screen reader mode, press SCAN, and select the name, Inventory count, and price list. Missing entries retry for five seconds; keep the mouse/popups clear. Failed price or stock checks need review.",
            GuideSurface.Main, ["SelectedProductHeader", "TradeQuoteRowsGrid", "GroupQuoteRowsGrid", "ReadPriceListButton", "GroupReadPriceListButton"]),
        new("7. Enable scanned price sharing",
            "In Settings > Calculator Behavior, enable Screen reader mode, then Scanned price sharing. Read and accept the sharing disclosure to send verified scans and receive community prices. Sharing is optional and initially OFF; this tutorial never enables it.\n\nAutomatically checked scans and complete OCR reviews can upload prices and Inventory stock. Manual edits are flagged. No screenshots, raw OCR, account data or personal weekly allowance are sent. A random installation ID and token are saved locally and reused across launches. Turning sharing OFF stops transfers but keeps saved credentials and the newest applied values.",
            "Under Screen reader mode, turn on Scanned price sharing and accept the disclosure when you want to participate. Verified scans can upload prices and stock. Sharing is optional; the tour does not turn it on.",
            GuideSurface.Settings, ["SharingSettingsRow", "ScreenReaderModeCheckBox", "CommunitySharingCheckBox"]),
        new("8. Refresh community prices",
            "Use the small refresh icon in the paper's upper-left corner to receive and apply the newest community prices and Inventory supply. Screen reader mode and Scanned price sharing must be enabled and connected.\n\nRefresh is limited to once per minute across all goods and tabs, including failed attempts. Prices use your own purchase discounts; newer local edits still win. Uploading a scan does not automatically download prices. There is no background polling or automatic price download on launch.",
            "This refresh icon receives and applies community prices and stock while sharing is connected. Refresh once per minute across all tabs. Uploading scans does not trigger a download; there is no background price polling.",
            GuideSurface.Main, ["CommunityRefreshButton", "CommunityRefreshInfo"]),
        new("9. Sharing connection status",
            "The bottom-left dot shows sharing status: green means connected; yellow means connecting, a temporary problem or rate limiting; red means a hard failure; gray means sharing is OFF.\n\nHover for a summary. Click yellow or red to open details, suggested fixes, the remaining wait and Retry. Retry stays disabled while a request or required wait is active. Startup can wait and retry; other automatic retries require a known rate-limit delay under one minute. OFF or closing the app cancels waits. Scan uploads are never queued or replayed; scan again after recovery.",
            "Watch the bottom-left dot: green connected, yellow waiting or a soft error, red failure, gray OFF. Hover for a summary; click yellow/red for fixes, wait time and Retry. Failed uploads are not replayed.",
            GuideSurface.Main, ["CommunityStatusButton"]),
        new("10. Load goods manually",
            "Set STOCK to what remains available and BUY PRICE to the observed unit cost. For Group/Barter, STOCK is your personal weekly remainder; scanned Inventory adds a separate post-supply cap without refilling it. It lasts only for the current session; scan again to refresh it. For Barter, MATERIAL COST is computed from the market values in Barter Materials.\n\nEnter PURCHASE QUANTITY; 0 means the maximum that fits stock, budget, weight, bundle slots, and weekly limits. Choose a letter if wanted, then press Purchase. This adds planner cargo only, not an in-game purchase.",
            "Set stock, buy price, and quantity, then Purchase. Quantity 0 loads as much as fits. Barter's material cost comes from your saved values.",
            GuideSurface.Main, ["ManualPurchaseInputs", "PurchaseActionButton"]),
        new("11. Cargo management",
            "The right pane shows held goods. Use its view button to switch between pocket slots and a list. Right-click a stack to remove it, or use CLEAR LOAD to empty the page's cargo.\n\nAuto requires an empty load. Switching to another page does not silently sell cargo. Capacity and stock are updated as you add/remove goods.",
            "Switch between pocket and list view. Right-click a stack to remove it, or CLEAR LOAD to empty the cargo. Auto needs an empty load.",
            GuideSurface.Main, ["TransportSlots", "TransportListView", "TransportViewToggleButton", "ClearLoadButton"]),
        new("12. Auto planning",
            "Open AUTO. For Trade/Group, choose SELECTED START or BEST OVERALL. Selected Start plans from the chosen town; Best Overall compares eligible sources with your cached destination quotes. Barter uses your selected outpost or combined pair.\n\nPress CALC after setting prices, stock, ownership, modifiers, and budget. Auto proposes mixed cargo; it does not buy goods in game. If a search reaches its budget, results are best found, not a guarantee of optimality.",
            "Selected Start plans from your chosen town; Best Overall compares towns. Press CALC to find loads using your prices, stock, budget, and transports.",
            GuideSurface.Main, ["AutoSelectedStartModeButton", "AutoBestOverallModeButton", "AutoCalculateButton"], 1),
        new("13. Auto results and letter overrides",
            "Trade/Group show Top 3 total-profit and profit-per-minute results; Barter shows Top 5 overall. VIEW ALL ROUTES opens the larger comparison chart. Select a result, review Custom Selection and its reward breakdown, then press Purchase to load that plan locally.\n\nLetter Override - Disabled lets Auto choose letters using Inventory market values. No letter forbids them. A specific letter forces it at 0 Gold for Auto estimates only. Manual/Load Profit still use Inventory values. Recalculate after changing the override.\n\nAuto may choose a Commerce Expansion Cover only when its extra cargo improves net Gold after the cover cost.",
            "Select a result, review it, then Purchase. VIEW ALL ROUTES shows more detail. The override lets Auto choose a letter, use none, or force one at 0 Gold. Manual/Load Profit use Inventory values.",
            GuideSurface.Main, ["AutoProfitResultsGrid", "AutoTimeResultsPanel", "AutoCustomSelectionList", "AutoCustomPlaceholder", "AutoLetterOverridePicker"], 1),
        new("14. Load Profit and selling",
            "Open LOAD PROFIT to compare destinations for the actual cargo. Columns include estimated profit, time, and Gold/minute; missing route times show --. Select the intended destination and letter. Hover rewards for costs, bonuses, and rounding.\n\nAfter selling in game, use Sell to record that planner load and clear its cargo. It records history only; it cannot perform the game sale. Inventory letter values and an active cover's once-per-trip cost are included in net Gold.",
            "Compare destinations for your load, then choose a destination and letter. After selling, press Sell to record the trip and clear the cargo.",
            GuideSurface.Main, ["DestinationTotalsList", "SellActionButton"], 2),
        new("15. Route map and travel estimates",
            "On LOAD PROFIT, select a destination and press the map button. Position the overlay over the game's minimap and follow the selected route across regions. The toolbar controls map/line visibility and click-through; it never detects your position.\n\nTravel times use client-map distances, selected transport speed, ferry schedules, and configured ferry/portal buffers. Unsupported routes show --. Combined Karu/Oasis routes choose the estimated faster starting order; Calida/Pera starts at Pera.",
            "Choose a destination and open the route map. Position it over your minimap. Times include ferry and portal buffers; -- means no estimate.",
            GuideSurface.Main, ["RouteMapButton", "RouteMapDestinationPicker"], 2),
        new("16. Route map popout",
            "The map popout shows the selected route, one region at a time. Drag its top bar to position it and resize the map to match your minimap.\n\nMAP shows the map background; turn it off for lines only. CLICK-THRU lets clicks pass through the map while the toolbar remains usable. Use the arrows to move between regions and X to close the popout.",
            "Drag the top bar to position the map. MAP toggles its background; CLICK-THRU passes clicks through it. Use the arrows for each region. This example shows Dunbarton to Bangor.",
            GuideSurface.RouteMap, ["Root", "MapModeButton", "ClickThroughButton", "PreviousButton", "NextButton"]),
        new("17. Letters and Expansion Cover",
            "Open Inventory with the bag icon. For letters, enter Have and Market Gold. Blank Have means untracked; 0 means none held. Blank/0 Market Gold excludes a letter from normal Auto selection. Auto can model buying a priced letter when none is held. Counts are manually tracked.\n\nA Commerce Expansion Cover adds 1 slot and 100 weight for one trip. Its default market value is 2,000,000 Gold. Auto uses it only when extra cargo pays for that value, even if owned; blank/0 disables consideration. The chosen cost stays fixed for loaded cargo until it is emptied. There is no manual cover-use toggle.",
            "Enter Have and Market Gold for letters and the cover. Auto includes their cost, even if owned. Blank/0 values disable Auto selection. The cover adds +1 slot/+100 weight when worthwhile.",
            GuideSurface.Inventory, ["LettersPaperFill"]),
        new("18. Mastery, enchants, and modifiers",
            "Set Commerce Mastery to your actual rank. Choose each accessory's prefix/suffix enchant and rolled percent when required. Select titles, partner buffs, capacity talents, potions, and speed modifiers that apply to your trip.\n\nOpen Merchant Ratings to edit post-specific levels. Capacity bonuses affect feasible loads; speed bonuses affect estimated time; reward bonuses affect the displayed breakdown. These are manual assumptions, not detected game effects.",
            "Set your mastery, enchants, and active bonuses. Merchant Ratings stores each post's level. Capacity affects load size; speed affects time; reward bonuses appear in breakdowns.",
            GuideSurface.Inventory, ["EnchantPaperFill", "MasteryPaperFill", "ModifierPaperFill"]),
        new("19. Barter material values",
            "Open Barter Materials with the auction-house icon. Enter per-unit Market Gold for tradable materials and on-hand quantities for the untradable materials in its lower list. Untradable market values remain read-only. Track other on-hand quantities in the shopping list. Gold per Ducat converts Ducat profit into a comparable Gold total.\n\nThe page compares barter offers with those material costs and your selected letter. Update market values when prices change; having materials does not make their market value zero. Use a row's copy icon to copy its item name.",
            "Enter material market values and quantities held. Gold per Ducat converts rewards to Gold. Owned materials still have a cost; untradable values are read-only.",
            GuideSurface.Materials, ["GoldPerDucatInput", "MaterialList", "OwnedMaterialList"]),
        new("20. Is a barter worth running?",
            "The right half of Barter Materials compares the gain per unit for each offer. Run it means estimated sale rewards exceed the material value; Sell mats means the materials are worth at least as much. Cards show recipe costs and the best entered or estimated sale, including Gold and converted Ducats.\n\nChoose a letter above the cards to compare its reward bonus here; this estimate does not include the letter's market cost. An asterisk means a material has no entered value and counts as 0. Rotating offers may be inactive. Check values and rotation before deciding; use each card's i bubble for the full calculation.",
            "Each card compares sale rewards with material cost: Run it or Sell mats. Choose a letter above to compare bonuses; its price is not deducted here. * marks a missing value counted as 0. The i bubble shows the calculation.",
            GuideSurface.Materials, ["PaperPanel", "LetterPicker"]),
        new("21. Barter shopping list",
            "On BARTER, load the exchange goods you intend to obtain. Use the shopping-list button below the cargo pane to see materials Needed, Have, and Still need.\n\nMarket Gold edits are shared with Barter Materials. Copy for Sheets copies a tab-separated table including per-unit values for pasting into Google Sheets. Review weekly quantities and current rotations in game before exchanging.",
            "This button opens the material shopping list for Barter cargo: Needed, Have, and Still need. Edit shared market values, or Copy for Sheets to paste the list.",
            GuideSurface.Main, ["ShoppingListButton"], 2),
        new("22. Settings, resets, and history",
            "The running version appears at the upper-left edge of the black title bar, with by ROOT50199 beneath the title. The full GitHub repository link at the bottom of Settings opens in your default browser.\n\n" +
            "Sharing startup retry waits use the server's supplied delay when available; 5s/10s are fallback delays for temporary privacy-read failures.\n\n" +
            "App updates in General: Check updates on app open is saved and ON by default. Turn it OFF for manual checks only; CHECK FOR UPDATES always works. Checks include stable and beta GitHub releases and send only normal connection metadata, not planner/account data. Downloads/installations require Yes in the version/size permission dialog. No leaves files unchanged. The verified Windows package replaces only app-owned files after closing this instance and restarts via a temporary Windows PowerShell helper. Settings/history stay intact; unsold cargo is not saved. Close other instances in the same folder and finish scans/calculations first. Errors remain in notifications; helper failures show recovery-folder details. No admin elevation or source-checkout updates.\n\n" +
            "General contains Always on top, Reset Window Positions and all tooltip switches, including detailed reward tooltips. Calculator Behavior contains Screen reader mode, automatic weekly restock, ferry/portal time buffers and Converted Gold/Ducats profit-display radio buttons. Barter profit remains Gold. Manual weekly stock refresh uses the separate reset icon beside the source post; ensure values match your remaining weekly stock.\n\nSave last scan region, dev-only Scan debug mode and Scanned price sharing are indented scanner suboptions. They disable when scanner mode is off; saved region/debug preferences remain selected. Turning scanner mode off also saves sharing OFF; turning scanning back on does not resume sharing automatically.\n\nUser and Dev builds share the same Cloudflare-hosted online service. Sharing sends automatically checked scans and complete scans you confirm in OCR review. Confirm all destinations, source price (not needed for Barter) and Inventory stock. Edits are flagged manual per source/stock/destination; unchanged values are reviewed OCR. Reviewed prices can update other planners. Cancelled or partial/unconfirmed reviews never upload. Missing or inconsistent OCR profits stay null, never invented from corrected sales. Reviewing renews the short-lived upload ticket within the same sharing session.\n\nThe info bubble shows the backend. ON/OFF, consented backend and sharing policy are saved; ON reconnects for that service/policy without a repeated prompt or automatic download. Legacy consent or a changed backend/policy turns sharing OFF until you accept again. A random installation ID and token are saved unencrypted in community-credentials.json beside the app and reused across launches. Keep that file private; copying it shares the installation identity. OFF keeps credentials but stops transfers, and saved credentials alone never enable sharing. Existing users accept this updated disclosure once. Reconnect verifies authorization with a short-lived ticket, without uploading observations or downloading prices. Rejected saved credentials remain disconnected rather than automatically registering a replacement. Failed connections keep ON. The bottom-left dot is green when connected, yellow for connecting/temporary errors/rate limits, red for hard failures, gray when OFF. Hover for a summary; click yellow/red for details, fixes, remaining wait and Retry. Startup honors known server rate-limit waits and retries temporary privacy-read failures twice (5s/10s). Otherwise automatic connection/read/ticket retries require a known rate-limit delay under one minute; long or unknown waits need manual retry. Refresh retries respect the global one-minute cooldown. OFF/close cancels waits. Ambiguous registrations and scan uploads are not replayed; scan again after recovery. Refresh explicitly using the dark paper-corner icon, at most once per minute; no polling or offline upload queue.\n\nNo character/account data, images, raw OCR or personal weekly allowance are transmitted or recorded by sharing. IP logs and new observations' installation links expire after 30 days; pre-policy links remain unchanged. Unused expired credentials are deleted. Individual price/stock history remains indefinitely. OFF/close retains newest applied local prices/supply with original times, recipient-effective buy prices and consumption. Personal weekly allowance stays separate; saved stock refunds unsold cargo because cargo is not persisted. Enter correct merchant levels/discount gear; recipients apply their own discounts. Newest manual/scan/community values win.\n\nCatalog sanity bounds are broad: quarter of the discounted historic minimum to four times the historic maximum for source buys, and quarter-minimum to four times maximum for the Barter median base. These only catch gross errors; exact auto-accept cross-checks and independent OCR agreement remain required.\n\nTrade History at the bottom records Sell loads and running totals. These are estimates based on sale-time inputs, not proof of an in-game transaction.",
            "Set scanning, always-on-top, help, and profit display here. Adjust weekly stock refresh and ferry/portal buffers. Trade History shows recorded trips; Reset Window Positions brings panels back.",
            GuideSurface.Settings, ["SettingsMenuCanvas"]),
        new("23. Help bubbles",
            "Small ?/i bubbles explain nearby controls. Click one or hover for one second to read it. Controls with bubbles do not repeat that help as a separate mouseover tooltip. Calculation hovers show detailed reward formulas.\n\nSettings lets you toggle help bubbles, calculation breakdowns, and item/status tips separately.",
            "Click a ?/i bubble, or hover for one second, for help. Hover calculation results for detailed formulas. Toggle the help categories in Settings.",
            GuideSurface.Materials, ["GoldPerDucatHelp", "UntradableMaterialsHelp", "BarterLetterHelp"]),
        new("24. Manual and saved profiles",
            "The book beside Settings opens this manual and can restart the tour. X or Escape exits at any step. Next/Back move between steps.\n\nconfig.json and trade-history.json live beside the executable. Use a writable folder and copy both files when upgrading. Each app folder has its own profile.",
            "The book opens this manual and restarts the tour. Your settings and history stay beside the app; copy them when upgrading. Press Finish to return.",
            GuideSurface.Main, ["ManualButton"])
    ];
}
